        self.add_cuda = load_inline(
            name="elementwise_add",
            cpp_sources="""
                // Define the custom CUDA kernel for element-wise addition
                __global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
                    int idx = blockIdx.x * blockDim.x + threadIdx.x;
                    if (idx < size) {
                        out[idx] = a[idx] + b[idx];
                    }
                }

                // Compile the inline CUDA code for element-wise addition
                torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
                    auto size = a.numel();
                    auto out = torch::zeros_like(a);

                    const int block_size = 256;
                    const int num_blocks = (size + block_size - 1) / block_size;

                    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

                    return out;
                }
            """,
            cuda_sources=elementwise_add_source,
            functions=["elementwise_add_cuda"],
            verbose=True,
            extra_cflags=[],
            extra_ldflags=[]
        )

        # Define the custom CUDA kernel for convolution operation
        self.conv3d_kernel = load_inline(
            name="custom_convolution",
            cpp_sources="""
                // Custom 3D convolution kernel implementation
                __global__ void custom_conv3d_kernel(const float* input, const float* output, int batch_size, int in_channels, int out_channels, int kernel_size, int stride, int padding, int dilation, int groups) {
                    // Calculate the number of blocks and threads for each dimension
                    int num_blocks = (batch_size + 1) / stride;
                    int block_size = max(1, kernel_size * stride);

                    // Calculate the offset for each output channel
                    int out_offset = (out_channels - 1) * block_size;

                    // Loop over input channels and compute the convolution result
                    for (int i = 0; i < in_channels; i++) {
                        int start_idx = (i + groups) * block_size;
                        for (int j = 0; j < kernel_size; j++) {
                            int k_offset = (j + dilation) * stride;
                            // Calculate the offset within the output tensor
                            int out_offset += (k_offset - i * in_channels) % (out_channels - 1);

                            // Apply convolution operation with padding and dilation
                            for (int c = 0; c < kernel_size; c++) {
                                int k_idx = i + groups * block_size + j * block_size + k_offset;
                                if (k_idx >= batch_size) break;
                                // Calculate the value from input tensor
                                float val = input[i, c, k_idx] * output[k_idx];
                                // Update the output tensor
                                output[out_offset + k_idx] += val;
                            }
                        }
                    }
                }

                // Compile the inline CUDA code for custom convolution operation
                torch::Tensor custom_convolution_cuda(torch::Tensor input, torch::Tensor output) {
                    auto batch_size = input.numel();
                    auto out = torch::zeros_like(output);

                    const int block_size = 256;
                    const int num_blocks = (batch_size + block_size - 1) / block_size;

                    custom_conv3d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), out.data_ptr<float>(), batch_size, in_channels, kernel_size, stride, padding, dilation, groups);

                    return out;
                }
            """,
            functions=["custom_convolution"],
            verbose=True,
            extra_cflags=[],
            extra_ldflags=[]
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 3D convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, depth, width, height).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, depth_out, width_out, height_out).
        """
        # Apply custom convolution operation
        return self.conv3d_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), x.data_ptr<float>(), x.numel(), in_channels, out_channels, kernel_size, stride, padding, dilation, groups)
